/* SWCS PARTIAL-WINDOW PROBE: after the bit-bang panel_init (panel lit), switch
 * to hardware SPI2 and draw ONE partial-window red rect (140..340 x 100..220).
 * With CONFIG_ESP32S3_SPI_SWCS=y the peripheral no longer auto-toggles hardware
 * FSPICS0 per transaction -> tests whether that per-transaction CS toggling was
 * corrupting partial CASET/RASET. If the red rect shows -> SWCS is the fix.
 * Restores GPIO afterward so the bit-bang demo path still works. */
static void spi_partial_probe(void)
{
  spi_lcd_init();
  if (g_spi == NULL) return;
  spi_begin();
  spi_window(140,340,100,220);
  spi_dc_data();
  { int y,x; for(x=0;x<201;x++){g_swap[2*x]=0xf8;g_swap[2*x+1]=0x00;}
    for(y=0;y<121;y++) SPI_SNDBLOCK(g_spi,g_swap,201*2); }
  spi_end();
  syslog(LOG_ERR,"[wslcd] SWCS partial-rect probe done; observe 8s\n");
  up_mdelay(8000);
  esp32s3_configgpio(PIN_MOSI,OUTPUT);esp32s3_configgpio(PIN_CLK,OUTPUT);esp32s3_configgpio(PIN_DC,OUTPUT);
  g_out=(*(volatile uint32_t *)REG_OUT)&~(MOSI_M|CLK_M|DC_M);
}

/* SPI_SELECT holds software CS (GPIO4, with SWCS=y) LOW across the WHOLE
 * transaction so a multi-byte command (CASET cmd + 4 params) is never
 * deselected mid-sequence. No-op if CS is hardware/tied-low. */
static void spi_begin(void){ SPI_LOCK(g_spi,true); SPI_SETMODE(g_spi,SPIDEV_MODE0); SPI_SETBITS(g_spi,8); SPI_SETFREQUENCY(g_spi,10000000); SPI_SELECT(g_spi,SPIDEV_DISPLAY(0),true); }
static void spi_end(void){ SPI_SELECT(g_spi,SPIDEV_DISPLAY(0),false); SPI_LOCK(g_spi,false); }

