/* ===== HYBRID: bit-bang the window COMMANDS (reliable), HW-SPI the bulk
 * PIXELS (fast). Sidesteps the partial-window-command bug entirely: the panel
 * only ever sees CASET/RASET/RAMWR from the flawless bit-bang path, and the
 * SPI2 engine is a pure pixel cannon (the case we proved works). S3 signal
 * indices verified from the register dump: FSPID_OUT=103, FSPICLK_OUT=101. */
static inline void pins_to_bitbang(void){
  esp32s3_gpio_matrix_out(PIN_MOSI,256,0,0); esp32s3_configgpio(PIN_MOSI,OUTPUT);
  esp32s3_gpio_matrix_out(PIN_CLK,256,0,0);  esp32s3_configgpio(PIN_CLK,OUTPUT);
  g_out=(*(volatile uint32_t *)REG_OUT)&~(MOSI_M|CLK_M|DC_M);
}
static inline void pins_to_spi(void){
  esp32s3_gpio_matrix_out(PIN_MOSI,103,0,0);   /* FSPID_OUT  -> GPIO1 */
  esp32s3_gpio_matrix_out(PIN_CLK,101,0,0);    /* FSPICLK_OUT-> GPIO5 */
}
static void hybrid_blit(int x0,int x1,int y0,int y1,const uint8_t *buffer,int stride){
  int rows=y1-y0+1, r; size_t rowb=(size_t)(x1-x0+1)*2, i;
  pins_to_bitbang();
  bb_window(x0,x1,y0,y1);              /* CASET/RASET/RAMWR via bit-bang */
  wreg(REG_OUT, g_out|DC_M);           /* DC high (data); MOSI/CLK idle low */
  pins_to_spi();                       /* hand pins to SPI2 for the blast */
  SPI_LOCK(g_spi,true);
  SPI_SETMODE(g_spi,SPIDEV_MODE0); SPI_SETBITS(g_spi,8); SPI_SETFREQUENCY(g_spi,10000000);
  for(r=0;r<rows;r++){ const uint8_t *p=buffer+(size_t)r*stride;
    for(i=0;i<rowb;i+=2){ g_swap[i]=p[i+1]; g_swap[i+1]=p[i]; }
    SPI_SNDBLOCK(g_spi,g_swap,rowb); }
  spi_idle();
  SPI_LOCK(g_spi,false);
}

