static void spi_lcd_init(void){
  g_spi = esp32s3_spibus_initialize(2);
  syslog(LOG_ERR,"[wslcd] SPI2 lcd handle=%p\n", g_spi);
  esp32s3_configgpio(PIN_DC,OUTPUT);
}

/* ===== SOLUTION 2: full-screen FRAMEBUFFER MIRRORING =====================
 * The pin-mode switch (GPIO<->SPI matrix) glitches the CS-tied-low panel, and
 * ANY partial-window command over HW-SPI never lands -- but a FULL-SCREEN
 * window+fill over HW-SPI is rock solid. So: keep GPIO1/5 LOCKED to SPI2 for
 * the whole run (no switching ever), set the panel window to full-screen ONCE,
 * and repeatedly re-blit an entire PSRAM framebuffer via the proven per-row
 * full-screen path. LVGL's putarea just updates the framebuffer (byte-swapped,
 * no panel access); a background thread streams the whole frame to GRAM. No
 * transaction ever touches a partial window or re-routes a pin -> no glitch. */
static uint8_t *g_fb;               /* XRES*YRES*2, panel byte order (hi,lo) */

static void full_refresh(void){
  int r; uint8_t rw=0x2C;
  esp32s3_gpiowrite(PIN_DC,false); SPI_SNDBLOCK(g_spi,&rw,1); spi_idle(); /* RAMWR */
  esp32s3_gpiowrite(PIN_DC,true);                                        /* data */
  for(r=0;r<YRES;r++) SPI_SNDBLOCK(g_spi,g_fb+(size_t)r*XRES*2,XRES*2);  /* proven per-row blast */
  spi_idle();
}

static int refresh_loop(int argc, char **argv){
  SPI_LOCK(g_spi,true);
  SPI_SETMODE(g_spi,SPIDEV_MODE0); SPI_SETBITS(g_spi,8);
  SPI_SETFREQUENCY(g_spi,10000000);
  /* full-screen window ONCE (CASET 0..XRES-1, RASET 0..YRES-1) */
  spi_cmd(0x2A); spi_dat(0); spi_dat(0); spi_dat((XRES-1)>>8); spi_dat((XRES-1)&0xff);
  spi_cmd(0x2B); spi_dat(0); spi_dat(0); spi_dat((YRES-1)>>8); spi_dat((YRES-1)&0xff);
  syslog(LOG_ERR,"[wslcd] fb-mirror thread up fb=%p\n", g_fb);
  for(;;){ full_refresh(); usleep(40000); }
  return 0;
}

