261	static int tflm_embed(const struct velapaw_frame *frame, float *out, int dim)
262	{
263	  if (g_interp == nullptr || frame == nullptr || out == nullptr || dim <= 0)
264	    {
265	      return -1;
266	    }
267	
268	  /* Preprocess: RGB uint8 -> normalized [-1,1] -> int8 per model input quant
269	   * (matches host normalization mean/std = 127.5). */
270	  float in_scale = g_input->params.scale;
271	  int   in_zp    = g_input->params.zero_point;
272	  if (in_scale == 0.0f)
273	    {
274	      in_scale = 1.0f / 128.0f;   /* symmetric fallback */
275	    }
276	  int n    = frame->width * frame->height * frame->channels;
277	  int in_n = g_input->bytes;
278	  for (int i = 0; i < n && i < in_n; i++)
279	    {
280	      float norm = ((float)frame->data[i] - 127.5f) / 127.5f;
281	      int q = (int)lroundf(norm / in_scale) + in_zp;
282	      if (q < -128) q = -128;
283	      if (q > 127)  q = 127;
284	      g_input->data.int8[i] = (int8_t)q;
285	    }
286	
287	  struct timespec t0;
288	  struct timespec t1;
289	  clock_gettime(CLOCK_MONOTONIC, &t0);
290	  TfLiteStatus status = g_interp->Invoke();
291	  clock_gettime(CLOCK_MONOTONIC, &t1);
292	  g_last_us = elapsed_us(&t0, &t1);
293	
294	  if (status != kTfLiteOk)
295	    {
296	      MicroPrintf("velapaw/tflm: Invoke failed");
297	      return -1;
298	    }
299	
300	  /* Dequantize the output tensor into the embedding, zero-pad, L2-normalize.
301	   * (person_detect output is 2 values; a real embedding model fills `dim`.) */
302	  TfLiteTensor *o   = g_interp->output(0);
303	  float        scale = o->params.scale;
304	  int          zp    = o->params.zero_point;
305	  int          olen  = o->bytes;   /* int8 element count */
306	
307	  for (int i = 0; i < dim; i++)
308	    {
309	      out[i] = 0.0f;
310	    }
311	
312	  for (int i = 0; i < olen && i < dim; i++)
313	    {
314	      out[i] = ((int)o->data.int8[i] - zp) * scale;
315	    }
316	
317	  float norm = 0.0f;
318	  for (int i = 0; i < dim; i++)
319	    {
320	      norm += out[i] * out[i];
321	    }
322	
323	  norm = sqrtf(norm);
324	  if (norm < 1e-6f)
325	    {
326	      norm = 1.0f;
327	    }
328	
329	  for (int i = 0; i < dim; i++)
330	    {
331	      out[i] /= norm;
332	    }
333	
334	  return 0;
335	}
