352	#ifdef VELAPAW_HAVE_BCS
353	/* Run the BCS network on a frame: *cls = 0 under / 1 ideal / 2 over,
354	 * *conf = softmax probability of that class. Returns 0 on success. */
355	extern "C" int velapaw_infer_bcs(const struct velapaw_frame *frame,
356	                                 int *cls, float *conf)
357	{
358	  if (g_bcs_interp == nullptr || g_bcs_input == nullptr || frame == nullptr)
359	    {
360	      return -1;
361	    }
362	
363	  int n    = frame->width * frame->height * frame->channels;
364	  int in_n = g_bcs_input->bytes;   /* uint8 input, 0-255 RGB (prep is in-model) */
365	  for (int i = 0; i < n && i < in_n; i++)
366	    {
367	      g_bcs_input->data.uint8[i] = frame->data[i];
368	    }
369	
370	  if (g_bcs_interp->Invoke() != kTfLiteOk)
371	    {
372	      return -1;
373	    }
374	
375	  TfLiteTensor *o = g_bcs_interp->output(0);
376	  float scale = o->params.scale;
377	  int   zp    = o->params.zero_point;
378	  int   best  = 0;
379	  float bestp = -1.0f;
380	  for (int i = 0; i < o->bytes; i++)
381	    {
382	      float p = ((int)o->data.uint8[i] - zp) * scale;
383	      if (p > bestp)
384	        {
385	          bestp = p;
386	          best  = i;
387	        }
388	    }
389	  if (cls)
390	    {
391	      *cls = best;
392	    }
393	  if (conf)
394	    {
395	      *conf = bestp;
396	    }
397	  return 0;
398	}
399	#endif
