233	/****************************************************************************
234	 * appetite / alert  (relative to each pet's DAILY LIMIT = the ration the
235	 * owner set, not a rolling average)
236	 ****************************************************************************/
237	
238	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
239	 * at the limit). 100% = ate its full daily allowance. */
240	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
241	{
242	  int today = velapaw_store_today_total(id);
243	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
244	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
245	}
246	
247	/* appetite-drop alert: the last completed day was under half the daily limit. */
248	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
249	{
250	  int yesterday = velapaw_store_day_total(id, 1);
251	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
252	}
