static void frame_to_565(const struct velapaw_frame *f, uint16_t *dst)
{
  int npx = f->width * f->height;
  for (int i = 0; i < npx; i++)
    {
      uint8_t r = f->data[i * 3 + 0];
      uint8_t g = f->data[i * 3 + 1];
      uint8_t b = f->data[i * 3 + 2];
      dst[i] = (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
    }
}

input.new_string:
static void frame_to_565(const struct velapaw_frame *f, uint16_t *dst)
{
  /* Rotate 90 deg clockwise while converting (the sensor is mounted rotated).
   * Square frame (128x128), so dims are unchanged. dst(dr,dc) = src(H-1-dc, dr). */
  int W = f->width, H = f->height;
  for (int dr = 0; dr < H; dr++)
    for (int dc = 0; dc < W; dc++)
      {
        int si = ((H - 1 - dc) * W + dr) * 3;
        uint8_t r = f->data[si + 0];
        uint8_t g = f->data[si + 1];
        uint8_t b = f->data[si + 2];
        dst[dr * W + dc] = (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
      }
}

